import std.concurrent as conc

pub type AppError = Failed(String)

pub fn main() effect net -> Result<(), AppError> {
    let xs = [1, 2, 3]
    scope {
        let t = task effect net { put(xs) }
        let _ = t.await()
    }
    return Ok(())
}

